<?php
use CaliChat\Core\Audit;
use CaliChat\Core\Db;
use CaliChat\Core\Platform;
use CaliChat\Services\Billing;

$title = 'Billing';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check(); $act = post('act'); $admin = (int)$u['id'];
    if ($act === 'paid') { $r = Billing::markPaid((int)post('id'), $admin, post('ref')); flash($r['ok'] ? 'Payment confirmed. The plan is active and the period extended.' : (string)$r['error'], $r['ok'] ? 'ok' : 'err'); }
    elseif ($act === 'void') { flash(Billing::void((int)post('id'), $admin) ? 'Invoice voided.' : 'That invoice was already settled.', 'ok'); }
    elseif ($act === 'issue') { $inv = Billing::issue((int)post('tenant_id'), post('plan'), max(1, min(12, (int)post('months', '1')))); flash($inv ? "Invoice {$inv['number']} issued." : 'Pick a tenant and a plan.', $inv ? 'ok' : 'err'); }
    elseif ($act === 'trial') { $tid = (int)post('tenant_id'); $days = max(1, min(365, (int)post('days', '14'))); if (Db::val("SELECT id FROM tenants WHERE id=?", [$tid])) { Db::update('tenants', ['billing_status' => 'trial', 'trial_ends_at' => gmdate('Y-m-d H:i:s', time() + $days * 86400)], 'id=?', [$tid]); Audit::log('trial_extend', 'tenant:' . $tid, "$days days", $tid); flash("Trial set to $days days from now."); } }
    elseif ($act === 'state') { $st = in_array(post('state'), ['active', 'cancelled'], true) ? post('state') : null; if ($st && Db::val("SELECT id FROM tenants WHERE id=?", [(int)post('tenant_id')])) { Db::update('tenants', ['billing_status' => $st] + ($st === 'active' ? ['current_period_end' => null] : []), 'id=?', [(int)post('tenant_id')]); Audit::log('billing_state', 'tenant:' . (int)post('tenant_id'), $st, (int)post('tenant_id')); flash($st === 'active' ? 'Set to active with no end date (complimentary).' : 'Subscription cancelled.'); } }
    elseif ($act === 'plan_save') {
        $code = preg_replace('/[^a-z0-9_]/', '', strtolower(post('code'))); if ($code === '' || post('name') === '') { flash('A code and a name are required.', 'err'); redirect('admin/billing'); }
        Db::q("INSERT INTO plans (code, name, price_lkr, monthly_message_limit, monthly_token_limit, max_users, description, is_public, sort) VALUES (?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name), price_lkr=VALUES(price_lkr), monthly_message_limit=VALUES(monthly_message_limit), monthly_token_limit=VALUES(monthly_token_limit), max_users=VALUES(max_users), description=VALUES(description), is_public=VALUES(is_public), sort=VALUES(sort)",
            [substr($code, 0, 30), mb_substr(post('name'), 0, 60), max(0, (float)post('price')), max(0, (int)post('messages')), max(0, (int)post('tokens')), max(1, (int)post('users', '5')), mb_substr(post('description'), 0, 200), isset($_POST['is_public']) ? 1 : 0, (int)post('sort')]);
        Audit::log('plan_save', $code); flash('Plan saved. Existing tenants keep their limits until their next payment is confirmed.');
    }
    elseif ($act === 'settings') { Platform::set('signup_enabled', isset($_POST['signup_enabled']) ? '1' : '0'); Platform::set('billing_bank_details', mb_substr((string)($_POST['bank'] ?? ''), 0, 800)); Audit::log('billing_settings'); flash('Saved.'); }
    redirect('admin/billing');
}
$claims = Db::all("SELECT i.*, t.name tname FROM invoices i JOIN tenants t ON t.id=i.tenant_id WHERE i.status='paid_claimed' ORDER BY i.claimed_at");
$open = Db::all("SELECT i.*, t.name tname FROM invoices i JOIN tenants t ON t.id=i.tenant_id WHERE i.status='issued' ORDER BY i.due_date LIMIT 50");
$paid = Db::all("SELECT i.*, t.name tname FROM invoices i JOIN tenants t ON t.id=i.tenant_id WHERE i.status='paid' ORDER BY i.paid_at DESC LIMIT 15");
$tenants = Db::all("SELECT id, name, plan, billing_status, trial_ends_at, current_period_end, signup_source, created_at FROM tenants ORDER BY (billing_status IN ('lapsed','past_due')) DESC, id DESC");
$plans = Billing::plans(false); $stBadge = ['trial' => 'warn', 'active' => 'ok', 'past_due' => 'err', 'lapsed' => 'err', 'cancelled' => 'gray'];
$mrr = (float)Db::val("SELECT COALESCE(SUM(p.price_lkr),0) FROM tenants t JOIN plans p ON p.code=t.plan WHERE t.billing_status='active' AND t.current_period_end IS NOT NULL AND t.status='active'");
$settled = fn($i) => '<form method="post" style="display:inline-flex;gap:6px;flex-wrap:wrap">' . csrf_field() . '<input type="hidden" name="act" value="paid"><input type="hidden" name="id" value="' . $i['id'] . '"><input name="ref" placeholder="Bank ref" value="' . e($i['payment_ref']) . '" aria-label="Bank reference" style="width:120px;padding:5px 9px"><button class="btn sm primary">Payment received</button></form> <form method="post" style="display:inline" data-confirm="Void this invoice?">' . csrf_field() . '<input type="hidden" name="act" value="void"><input type="hidden" name="id" value="' . $i['id'] . '"><button class="btn sm danger">Void</button></form>';
?>
<div class="page-head"><div><h1>Platform <span class="accent">Billing</span></h1><p>Plans, invoices and who has paid. Businesses pay by bank transfer; you confirm each payment here.</p></div></div>
<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr));margin-bottom:22px">
  <div class="card stat"><div class="muted small">Monthly recurring (active, paid)</div><div class="big">Rs. <?= num($mrr) ?></div></div>
  <div class="card stat"><div class="muted small">Waiting for you to confirm</div><div class="big"><?= count($claims) ?></div><div class="foot">payments claimed</div></div>
  <div class="card stat"><div class="muted small">Open invoices</div><div class="big"><?= count($open) ?></div></div>
  <div class="card stat"><div class="muted small">On trial</div><div class="big"><?= count(array_filter($tenants, fn($t) => $t['billing_status'] === 'trial')) ?></div><div class="foot"><?= count(array_filter($tenants, fn($t) => in_array($t['billing_status'], ['past_due', 'lapsed'], true))) ?> overdue or lapsed</div></div></div>

<?php if ($claims): ?><div class="card" style="margin-bottom:22px;border-color:var(--brand)"><h3>Confirm these payments</h3><p class="sub">The business says it has paid. Check your bank statement for the reference first.</p><div class="tablewrap"><table><thead><tr><th>Invoice</th><th>Business</th><th class="num">Amount</th><th>Reference</th><th></th></tr></thead><tbody><?php foreach ($claims as $i): ?><tr><td><b><?= e($i['number']) ?></b><div class="muted small"><?= e($i['description']) ?></div></td><td><?= e($i['tname']) ?></td><td class="num">Rs. <?= num($i['amount']) ?></td><td class="mono"><?= e($i['payment_ref']) ?><div class="muted small"><?= ago($i['claimed_at']) ?></div></td><td><?= $settled($i) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>

<div class="grid" style="grid-template-columns:1.4fr 1fr;align-items:start;margin-bottom:22px">
<div class="card"><h3>Tenants</h3><div class="tablewrap"><table><thead><tr><th>Business</th><th>Plan</th><th>Status</th><th>Until</th><th></th></tr></thead><tbody><?php foreach ($tenants as $t): ?><tr><td><b><?= e($t['name']) ?></b><div class="muted small"><?= $t['signup_source'] ? 'self sign-up · ' : '' ?>since <?= e(substr($t['created_at'], 0, 10)) ?></div></td><td><?= e($t['plan']) ?></td><td><span class="badge <?= $stBadge[$t['billing_status']] ?>"><?= e(str_replace('_', ' ', $t['billing_status'])) ?></span></td>
  <td class="small"><?= e(substr((string)($t['billing_status'] === 'trial' ? $t['trial_ends_at'] : $t['current_period_end']), 0, 10) ?: 'no end date') ?></td>
  <td style="white-space:nowrap"><form method="post" style="display:inline-flex;gap:4px"><?= csrf_field() ?><input type="hidden" name="act" value="trial"><input type="hidden" name="tenant_id" value="<?= $t['id'] ?>"><input name="days" type="number" min="1" value="14" aria-label="Trial days" style="width:56px;padding:4px 8px"><button class="btn sm" title="Restart a trial of this many days">Trial</button></form>
    <form method="post" style="display:inline"><?= csrf_field() ?><input type="hidden" name="act" value="state"><input type="hidden" name="tenant_id" value="<?= $t['id'] ?>"><input type="hidden" name="state" value="<?= $t['billing_status'] === 'cancelled' || $t['billing_status'] === 'lapsed' ? 'active' : 'cancelled' ?>"><button class="btn sm <?= $t['billing_status'] === 'cancelled' || $t['billing_status'] === 'lapsed' ? 'primary' : 'danger' ?>" title="Active with no end date = complimentary"><?= $t['billing_status'] === 'cancelled' || $t['billing_status'] === 'lapsed' ? 'Reactivate' : 'Cancel' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="stack">
<form method="post" class="card stack"><?= csrf_field() ?><input type="hidden" name="act" value="issue"><h3>Issue an invoice</h3><label>Business<select name="tenant_id"><?php foreach ($tenants as $t): ?><option value="<?= $t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></label>
  <div class="row"><label>Plan<select name="plan"><?php foreach ($plans as $p): ?><option value="<?= e($p['code']) ?>"><?= e($p['name']) ?> (Rs. <?= num($p['price_lkr']) ?>)</option><?php endforeach; ?></select></label><label>Months<input name="months" type="number" min="1" max="12" value="1"></label></div><button class="btn">Issue</button></form>
<form method="post" class="card stack"><?= csrf_field() ?><input type="hidden" name="act" value="settings"><h3>Sign-up and payment details</h3>
  <label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="signup_enabled" value="1" <?= Billing::signupOpen() ? 'checked' : '' ?> style="width:auto"> Allow new businesses to sign up themselves</label>
  <label>Bank details shown to businesses <small>account name, number, bank, branch</small><textarea name="bank" rows="4"><?= e(Billing::bankDetails()) ?></textarea></label><button class="btn">Save</button><p class="muted small" style="margin:0">Sign-up page: <span class="mono"><?= e(abs_url('signup')) ?></span></p></form>
</div></div>

<?php if ($open): ?><div class="card" style="margin-bottom:22px"><h3>Open invoices</h3><div class="tablewrap"><table><thead><tr><th>Invoice</th><th>Business</th><th class="num">Amount</th><th>Due</th><th></th></tr></thead><tbody><?php foreach ($open as $i): ?><tr><td><b><?= e($i['number']) ?></b><div class="muted small"><?= e($i['description']) ?></div></td><td><?= e($i['tname']) ?></td><td class="num">Rs. <?= num($i['amount']) ?></td><td class="small"><?= e($i['due_date']) ?></td><td><?= $settled($i) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>

<div class="card" style="margin-bottom:22px"><h3>Plans</h3><p class="sub">Limits apply when a payment is confirmed. A plan that is not public cannot be chosen by businesses.</p>
<?php foreach ($plans as $p): ?><form method="post" style="display:grid;grid-template-columns:90px 1fr 110px 100px 130px 70px 1fr auto auto;gap:8px;align-items:center;margin-bottom:8px;overflow-x:auto"><?= csrf_field() ?><input type="hidden" name="act" value="plan_save"><input name="code" value="<?= e($p['code']) ?>" aria-label="Code" readonly><input name="name" value="<?= e($p['name']) ?>" aria-label="Name"><input name="price" type="number" value="<?= e($p['price_lkr']) ?>" aria-label="Price in rupees"><input name="messages" type="number" value="<?= (int)$p['monthly_message_limit'] ?>" aria-label="AI replies a month"><input name="tokens" type="number" value="<?= (int)$p['monthly_token_limit'] ?>" aria-label="Tokens a month"><input name="users" type="number" value="<?= (int)$p['max_users'] ?>" aria-label="Team members"><input name="description" value="<?= e($p['description']) ?>" aria-label="Description"><label style="white-space:nowrap"><input type="checkbox" name="is_public" value="1" <?= $p['is_public'] ? 'checked' : '' ?> style="width:auto"> public</label><input type="hidden" name="sort" value="<?= (int)$p['sort'] ?>"><button class="btn sm">Save</button></form><?php endforeach; ?>
<form method="post" style="display:grid;grid-template-columns:90px 1fr 110px 100px 130px 70px 1fr auto auto;gap:8px;align-items:center;overflow-x:auto"><?= csrf_field() ?><input type="hidden" name="act" value="plan_save"><input name="code" placeholder="code" aria-label="New plan code" required><input name="name" placeholder="Name" aria-label="Name" required><input name="price" type="number" placeholder="Rs." aria-label="Price"><input name="messages" type="number" placeholder="replies" aria-label="Replies"><input name="tokens" type="number" placeholder="tokens" aria-label="Tokens"><input name="users" type="number" placeholder="users" aria-label="Users"><input name="description" placeholder="Description" aria-label="Description"><label style="white-space:nowrap"><input type="checkbox" name="is_public" value="1" checked style="width:auto"> public</label><input type="hidden" name="sort" value="9"><button class="btn sm primary">Add plan</button></form>
<p class="muted small" style="margin:10px 0 0">Columns: code · name · price (Rs./month) · AI replies/month · tokens/month · team members · description.</p></div>

<?php if ($paid): ?><div class="card"><h3>Recently paid</h3><div class="tablewrap"><table><tbody><?php foreach ($paid as $i): ?><tr><td><b><?= e($i['number']) ?></b></td><td><?= e($i['tname']) ?></td><td class="num">Rs. <?= num($i['amount']) ?></td><td class="mono small"><?= e($i['payment_ref']) ?></td><td class="muted small"><?= ago($i['paid_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
